// ── Validation & Lookup Helpers ──────────────────────────────────────────

export interface OntologyValidationError {
  field: string;
  path: string;
  message: string;
}

export interface OntologyValidationResult {
  valid: boolean;
  classCurie: string;
  errors: OntologyValidationError[];
}

export function getOntologyClassMeta(curie: string): OntologyClassMeta | undefined {
  return ONTOLOGY_CLASSES[curie];
}

export function getClassesByStereotype(stereotype: UfoStereotypeCurie): OntologyClassMeta[] {
  return Object.values(ONTOLOGY_CLASSES).filter((c) => c.stereotype === stereotype);
}

function collectSuperClasses(curie: string, visited = new Set<string>()): string[] {
  if (visited.has(curie)) return [];
  visited.add(curie);
  const meta = ONTOLOGY_CLASSES[curie];
  if (!meta) return [curie];
  const out = [curie];
  for (const sc of meta.superClasses) {
    out.push(...collectSuperClasses(sc, visited));
  }
  return out;
}

export function validateOntologyInstance(
  classCurie: string,
  instance: Record<string, unknown>,
): OntologyValidationResult {
  const errors: OntologyValidationError[] = [];
  const chain = collectSuperClasses(classCurie);
  for (const cls of chain) {
    const constraints = ONTOLOGY_SHAPES[cls] ?? [];
    for (const c of constraints) {
      const raw = instance[c.fieldName];
      const values = raw === undefined || raw === null ? [] : Array.isArray(raw) ? raw : [raw];
      if (c.minCount !== undefined && values.length < c.minCount) {
        errors.push({
          field: c.fieldName,
          path: c.path,
          message: c.message ?? `${c.path} requires at least ${c.minCount} value(s).`,
        });
      }
      if (c.maxCount !== undefined && values.length > c.maxCount) {
        errors.push({
          field: c.fieldName,
          path: c.path,
          message: c.message ?? `${c.path} allows at most ${c.maxCount} value(s).`,
        });
      }
      for (const v of values) {
        if (c.allowedValues && c.allowedValues.length > 0 && !c.allowedValues.includes(String(v))) {
          errors.push({
            field: c.fieldName,
            path: c.path,
            message: c.message ?? `${c.path} value "${String(v)}" must be one of [${c.allowedValues.join(", ")}].`,
          });
        }
        if (c.minInclusive !== undefined && (typeof v !== "number" || v < c.minInclusive)) {
          errors.push({
            field: c.fieldName,
            path: c.path,
            message: c.message ?? `${c.path} must be >= ${c.minInclusive}.`,
          });
        }
      }
    }
  }
  return { valid: errors.length === 0, classCurie, errors };
}
